@import "@fontsource-variable/inter/opsz.css";
@import "@fontsource/ibm-plex-mono/400.css";
@import "@fontsource/ibm-plex-mono/500.css";

/* Light (the sibling): a soft white page, white cards, near-black text with the same four
   steps of grey, a dark pill button, and the same pale blue/lavender glow and lime. */
:root {
  --background: oklch(0.985 0.001 248);
  --foreground: oklch(0.235 0.008 271);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.235 0.008 271);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.235 0.008 271);
  --primary: oklch(0.285 0.011 271);
  --primary-foreground: oklch(0.985 0.001 248);
  --secondary: oklch(0.955 0.002 248);
  --secondary-foreground: oklch(0.285 0.011 271);
  --muted: oklch(0.955 0.002 248);
  --muted-foreground: oklch(0.541 0.012 262);
  --accent: oklch(0.935 0.003 248);
  --accent-foreground: oklch(0.235 0.008 271);
  --destructive: oklch(0.6 0.2 23);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0 0 0 / 8%);
  --input: oklch(0 0 0 / 12%);
  --ring: oklch(0.567 0.159 275);
  --highlight: oklch(0.92 0.201 114);
  --highlight-foreground: oklch(0.139 0.003 246);
  --glow: oklch(0.885 0.06 253);
  --chart-1: oklch(0.62 0.2 23);
  --chart-2: oklch(0.637 0.175 147);
  --chart-3: oklch(0.72 0.13 64);
  --chart-4: oklch(0.65 0.12 196);
  --chart-5: oklch(0.905 0.055 299);
  --sidebar: oklch(0.97 0.002 248);
  --sidebar-foreground: oklch(0.235 0.008 271);
  --sidebar-primary: oklch(0.567 0.159 275);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.935 0.003 248);
  --sidebar-accent-foreground: oklch(0.235 0.008 271);
  --sidebar-border: oklch(0 0 0 / 8%);
  --sidebar-ring: oklch(0.567 0.159 275);

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 80rem;
  --page-gutter: 1.5rem;
  --section-y: clamp(3rem, 1rem + 6vw, 8rem);
}

/* Dark (the faithful mode): #08090a page, #0f1011 / #161718 panels, white-8% hairlines,
   #f7f8f8 headings over #8a8f98 body grey, a #e5e5e6 pill button that whitens on hover,
   a pale blue glow and an electric lime for the two colour cards. */
.dark {
  --background: oklch(0.139 0.003 246);
  --foreground: oklch(0.978 0.001 197);
  --card: oklch(0.172 0.003 248);
  --card-foreground: oklch(0.978 0.001 197);
  --popover: oklch(0.204 0.003 248);
  --popover-foreground: oklch(0.978 0.001 197);
  --primary: oklch(0.922 0.001 286);
  --primary-foreground: oklch(0.139 0.003 246);
  --secondary: oklch(0.204 0.003 248);
  --secondary-foreground: oklch(0.978 0.001 197);
  --muted: oklch(0.204 0.003 248);
  --muted-foreground: oklch(0.649 0.015 262);
  --accent: oklch(1 0 0 / 8%);
  --accent-foreground: oklch(0.978 0.001 197);
  --destructive: oklch(0.655 0.201 23);
  --destructive-foreground: oklch(0.978 0.001 197);
  --border: oklch(1 0 0 / 8%);
  --input: oklch(1 0 0 / 12%);
  --ring: oklch(0.567 0.159 275);
  --highlight: oklch(0.92 0.201 114);
  --highlight-foreground: oklch(0.139 0.003 246);
  --glow: oklch(0.91 0.045 253);
  --chart-1: oklch(0.655 0.201 23);
  --chart-2: oklch(0.637 0.175 147);
  --chart-3: oklch(0.843 0.093 64);
  --chart-4: oklch(0.839 0.086 196);
  --chart-5: oklch(0.93 0.04 299);
  --sidebar: oklch(0.172 0.003 248);
  --sidebar-foreground: oklch(0.978 0.001 197);
  --sidebar-primary: oklch(0.567 0.159 275);
  --sidebar-primary-foreground: oklch(0.978 0.001 197);
  --sidebar-accent: oklch(0.204 0.003 248);
  --sidebar-accent-foreground: oklch(0.978 0.001 197);
  --sidebar-border: oklch(1 0 0 / 8%);
  --sidebar-ring: oklch(0.567 0.159 275);
}
